_not_independent":false,"ao_support_area_missing":false,"ao_support_wrong_topbar_area":false,"ao_support_bad_link":false,"ao_support_unapproved_availability":false,"ao_seed_as_runtime_authority":true},"esperado":true}]}},{"codigo":"S22AO-176-1","legacy_id":176,"relacionadas":["S22AO-176-2"],"coberturas":[{"legacy_id":176,"estado_cobertura":"PARCIAL","residual":"Falta reconciliar autoridad física de lf_ops.modelos_priorizacion con lf_global_config y modelado editable de criterios/variables; no se fija fórmula como único modelo ni se modifica runtime.","diferencias":"Decisión explícita del dueño 2026-11-26, contraste de descripción y valor_config; Falta reconciliar autoridad física de lf_ops.modelos_priorizacion con lf_global_config y modelado editable de criterios/variables; no se fija fórmula como único modelo ni se modifica runtime."}],"paquete":{"tipo":"NUEVA","codigo":"S22AO-176-1","clave":"s22ao_legacy_176_0","familia":"OFFERS_INSTALLMENTS","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_HOME","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Modelo parametrizable de priorización de ofertas","descripcion":"BLOQUEAR scoring de multi oferta que fije criterios o variables en código, o no use configuración gobernada editable sin deploy. Modelo inicial MOD_PRIOR_MVP_V1 en lf_ops.modelos_priorizacion: descuento relativo con {param:OFFERS.PRIORITY_WEIGHT_DISCOUNT}, accesibilidad por monto con {param:OFFERS.PRIORITY_WEIGHT_AMOUNT} y urgencia normalizada con {param:OFFERS.PRIORITY_WEIGHT_URGENCY}; referencias {param:OFFERS.PRIORITY_REFERENCE_AMOUNT} y {param:OFFERS.PRIORITY_REFERENCE_DAYS}. Fórmula legado pondera descuento relativo, accesibilidad y días de vigencia normalizados; desempate mayor descuento; prioridad crítica bajo {param:OFFERS.PRIORITY_CRITICAL_URGENCY_HOURS}. Recalibración sugerida con muestra {param:OFFERS.PRIORITY_RECALIBRATION_SAMPLE}, no automática. Criterios, variables, pesos y referencias editables; no imponer nuevo modelo activo. Parámetros en public.lf_global_config. Binding runtime pendiente; no modifica IG ni materializa estructuras pendientes.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/176","solicitante":"Cristhian / Claude S22-AO"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"ao_multi_offer_scoring"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"ao_priority_weights_hardcoded"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"ao_priority_reference_hardcoded"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ao_priority_criteria_fixed"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ao_priority_variables_fixed"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ao_priority_model_not_governed"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ao_priority_formula_wrong"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ao_priority_tiebreak_wrong"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ao_priority_critical_not_first"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ao_priority_recalibration_forced"},"der":{"lit":true}}},"der":{"op":"!=","izq":{"hecho":"ao_weight_discount"},"der":{"param":"OFFERS.PRIORITY_WEIGHT_DISCOUNT"}}},"der":{"op":"!=","izq":{"hecho":"ao_weight_amount"},"der":{"param":"OFFERS.PRIORITY_WEIGHT_AMOUNT"}}},"der":{"op":"!=","izq":{"hecho":"ao_weight_urgency"},"der":{"param":"OFFERS.PRIORITY_WEIGHT_URGENCY"}}},"der":{"op":"!=","izq":{"hecho":"ao_reference_amount"},"der":{"param":"OFFERS.PRIORITY_REFERENCE_AMOUNT"}}},"der":{"op":"!=","izq":{"hecho":"ao_reference_days"},"der":{"param":"OFFERS.PRIORITY_REFERENCE_DAYS"}}},"der":{"op":"y","izq":{"op":"<","izq":{"hecho":"ao_remaining_hours"},"der":{"param":"O