alse}]}}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; hashes jsonb:='{}'; hash_all text; t record;
BEGIN
 IF lf_ops.nucleo_param_valor_v1('B2B.INSTALLMENT_CURRENCY_PRECISION_DECIMALS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='B2B' AND config_key='INSTALLMENT_CURRENCY_PRECISION_DECIMALS' AND hecho='ao_precision') THEN RAISE EXCEPTION 'S22AO_PARAM_PREFLIGHT B2B.INSTALLMENT_CURRENCY_PRECISION_DECIMALS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('B2B.INSTALLMENT_ALLOWED_DIFFERENCE') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='B2B' AND config_key='INSTALLMENT_ALLOWED_DIFFERENCE' AND hecho='ao_difference') THEN RAISE EXCEPTION 'S22AO_PARAM_PREFLIGHT B2B.INSTALLMENT_ALLOWED_DIFFERENCE'; END IF;
 IF lf_ops.nucleo_param_valor_v1('B2B.INSTALLMENT_DEFAULT_MAX_TERMS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='B2B' AND config_key='INSTALLMENT_DEFAULT_MAX_TERMS' AND hecho='ao_default_max_terms') THEN RAISE EXCEPTION 'S22AO_PARAM_PREFLIGHT B2B.INSTALLMENT_DEFAULT_MAX_TERMS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('B2B.INITIAL_PAYMENT_ACTIVE_MIN_EXCLUSIVE') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='B2B' AND config_key='INITIAL_PAYMENT_ACTIVE_MIN_EXCLUSIVE' AND hecho='ao_initial_payment_amount') THEN RAISE EXCEPTION 'S22AO_PARAM_PREFLIGHT B2B.INITIAL_PAYMENT_ACTIVE_MIN_EXCLUSIVE'; END IF;
 IF lf_ops.nucleo_param_valor_v1('B2B.INSTALLMENT_EXCEL_ENTRY_SCREEN_COUNT') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='B2B' AND config_key='INSTALLMENT_EXCEL_ENTRY_SCREEN_COUNT' AND hecho='ao_excel_screen_count') THEN RAISE EXCEPTION 'S22AO_PARAM_PREFLIGHT B2B.INSTALLMENT_EXCEL_ENTRY_SCREEN_COUNT'; END IF;
 IF lf_ops.nucleo_param_valor_v1('OFFERS.PRIORITY_WEIGHT_DISCOUNT') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='OFFERS' AND config_key='PRIORITY_WEIGHT_DISCOUNT' AND hecho='ao_weight_discount') THEN RAISE EXCEPTION 'S22AO_PARAM_PREFLIGHT OFFERS.PRIORITY_WEIGHT_DISCOUNT'; END IF;
 IF lf_ops.nucleo_param_valor_v1('OFFERS.PRIORITY_WEIGHT_AMOUNT') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='OFFERS' AND config_key='PRIORITY_WEIGHT_AMOUNT' AND hecho='ao_weight_amount') THEN RAISE EXCEPTION 'S22AO_PARAM_PREFLIGHT OFFERS.PRIORITY_WEIGHT_AMOUNT'; END IF;
 IF lf_ops.nucleo_param_valor_v1('OFFERS.PRIORITY_WEIGHT_URGENCY') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='OFFERS' AND config_key='PRIORITY_WEIGHT_URGENCY' AND hecho='ao_weight_urgency') THEN RAISE EXCEPTION 'S22AO_PARAM_PREFLIGHT OFFERS.PRIORITY_WEIGHT_URGENCY'; END IF;
 IF lf_ops.nucleo_param_valor_v1('OFFERS.PRIORITY_REFERENCE_AMOUNT') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='OFFERS' AND config_key='PRIORITY_REFERENCE_AMOUNT' AND hecho='ao_reference_amount') THEN RAISE EXCEPTION 'S22AO_PARAM_PREFLIGHT OFFERS.PRIORITY_REFERENCE_AMOUNT'; END IF;
 IF lf_ops.nucleo_param_valor_v1('OFFERS.PRIORITY_REFERENCE_DAYS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='OFFERS' AND config_key='PRIORITY_REFERENCE_DAYS' AND hecho='ao_reference_days') THEN RAISE EXCEPTION 'S22AO_PARAM_PREFLIGHT OFFERS.PRIORITY_REFERENCE_DAYS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('OFFERS.PRIORITY_CRITICAL_URGENCY_HOURS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='OFFERS' AND config_key='PRIORITY_CRITICAL_URGENCY_HOURS' AND hecho='ao_remaining_hours') THEN RAISE EXCEPTION 'S22AO_PARAM_PREFLIGHT OFFERS.PRIORITY_CRITICAL_URGENCY_HOURS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('OFFERS.PRIORITY_RECALIBRATION_SAMPLE') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='OFFERS' AND config_key='PRIORITY_RECALIBRATION_SAMPLE' AND hecho='ao_recalibration_sample') THEN RAISE EXCEPTION 'S22AO_PARAM_PREFLIGHT OFFERS.PRIORITY_RECALIBRATION_SAMPLE'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22AO_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 h:=lf_ops.nucleo_hash_paquete_v1(cd,1); hashes:=hashes||jsonb_build_object(cd,h);
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22AO_VECTOR_FAIL %',cd; END IF; END LOOP;
 END LOOP;
 SELECT string_agg(j.key||'='||j.value,',' ORDER BY j.key) INTO hash_all FROM jsonb_each_text(hashes) j;
 RAISE EXCEPTION 'S22AO_HASH_ALL %',hash_all;
END $ao$;
COMMIT;
